verus! {
    // Replace all occurrences of `old_char` in `str1` with `new_char`,
    // returning a new Vec<char> of the same length, such that
    // for every index i,
    //   if str1[i] == old_char then result[i] == new_char
    //   else                   result[i] == str1[i]
    fn replace_chars(str1: &Vec<char>, old_char: char, new_char: char) -> (res: Vec<char>)
        ensures
            // The result has the same length as the input
            res.len() == str1.len(),
        ensures
            // For every valid index, the character is replaced exactly when it matches old_char
            forall |i: usize| i < str1.len() ==>
                if str1[i] == old_char {
                    res[i] == new_char
                } else {
                    res[i] == str1[i]
                }
    {
        // Prepare an empty vector with capacity = input length
        let mut res: Vec<char> = Vec::with_capacity(str1.len());
        let mut idx: usize = 0;
        // Process each index from 0 up to str1.len()
        while idx < str1.len()
            invariant
                // idx never exceeds the input length
                idx <= str1.len(),
            invariant
                // We have built exactly idx characters so far
                res.len() == idx,
            invariant
                // For all positions j < idx, the replacement property holds
                forall |j: usize| j < idx ==>
                    if str1[j] == old_char {
                        res[j] == new_char
                    } else {
                        res[j] == str1[j]
                    },
            decreases
                str1.len() - idx
        {
            let c = str1[idx];
            if c == old_char {
                res.push(new_char);
                // Immediately assert that the newly pushed character satisfies the spec
                assert(res[idx] == new_char);
            } else {
                res.push(c);
                assert(res[idx] == c);
            }
            idx += 1;
        }
        res
    }
}

